MOVES = [('PROJECT_INSTRUCTIONS.md', 'v3.95 (October 13, 2026): No rule changed in this document. ONE\n', 'Functional for Claude, readable for human, signal preserved.\n', 'documentation/PROJECT_INSTRUCTIONS_HISTORY.md', '(Moved down from the resident protocol on 2026-10-14 when\nv3.97 made a fourth entry.)\n', '(Moved down from the resident protocol on 2026-10-15 when\nv3.98 made a fourth entry.)\n')]


class PatchError(Exception):
    pass


def read(rel):
    path = os.path.join(ROOT, rel)
    if not os.path.exists(path):
        raise PatchError("missing file: %s (is this the orrery folder?)" % rel)
    raw = open(path, "rb").read()
    return raw.replace(b"\r\n", b"\n").decode("utf-8"), (b"\r\n" in raw)


def fingerprint(rel, text):
    if rel == "PROJECT_INSTRUCTIONS.md":
        a = text.index(ZONE_A)
        b = text.index(ZONE_B) + len(ZONE_B)
        text = text[:a] + text[b:]
    return hashlib.md5(text.encode("utf-8")).hexdigest()


def main():
    log = []
    notes = []
    texts = {}
    crlf = {}
    try:
        for rel, content in NEW_FILES.items():
            path = os.path.join(ROOT, rel)
            if os.path.exists(path):
                have, _c = read(rel)
                if have != content:
                    raise PatchError("%s already exists with other content; "
                                     "nothing was overwritten" % rel)
                notes.append("note: %s already present, identical" % rel)
            else:
                log.append("ok  new   %s" % rel)
        targets = sorted(set([e[0] for e in EDITS] + [m[0] for m in MOVES]
                             + [m[3] for m in MOVES]))
        for rel in targets:
            texts[rel], crlf[rel] = read(rel)
        for rel, want in FINGERPRINTS.items():
            got = fingerprint(rel, texts[rel])
            if got != want:
                raise PatchError("BASE MOVED: %s is not the file this patch was "
                                 "built against (ffd6c36a)" % rel)
            log.append("ok  base  %s matches ffd6c36a" % rel)

        # Where We Are: edit above the marker only
        if texts[WWA].count(MARKER) != 1:
            raise PatchError("ANCHOR FAIL [%s run-record marker]" % WWA)
        cut = texts[WWA].index(MARKER)
        wwa_top, wwa_bottom = texts[WWA][:cut], texts[WWA][cut:]

        for rel, label, alts in EDITS:
            text = wwa_top if rel == WWA else texts[rel]
            done = False
            for old, new in alts:
                n = text.count(old)
                if n == 1:
                    if new is None:
                        notes.append("note: %s %s left as it is: "
                                     "patch_L442_3 has not run yet and "
                                     "rewrites that line" % (rel, label))
                    else:
                        text = text.replace(old, new)
                        log.append("ok  edit  %-44s %s" % (rel, label))
                    done = True
                    break
                if n > 1:
                    raise PatchError("ANCHOR FAIL [%s %s]: %d matches"
                                     % (rel, label, n))
            if not done:
                raise PatchError("ANCHOR FAIL [%s %s]: not found: %r"
                                 % (rel, label, alts[0][0][:70]))
            if rel == WWA:
                wwa_top = text
            else:
                texts[rel] = text

        for src, start, end, dst, after, trailer in MOVES:
            s = texts[src]
            if s.count(start) != 1 or s.count(end) != 1:
                raise PatchError("ANCHOR FAIL [%s move %r]" % (src, start[:40]))
            a, b = s.index(start), s.index(end)
            if b <= a:
                raise PatchError("ANCHOR FAIL [%s move order]" % src)
            moved = s[a:b]
            texts[src] = s[:a] + s[b:]
            d = texts[dst]
            if d.count(after) != 1:
                raise PatchError("ANCHOR FAIL [%s insert after %r]"
                                 % (dst, after[:40]))
            i = d.index(after) + len(after)
            texts[dst] = d[:i] + "\n" + moved + trailer + d[i:]
            log.append("ok  move  %s -> %s" % (src, dst))

        above = wwa_top.count("\n")
        if above > WWA_CAP:
            raise PatchError("%s would stand %d lines above the marker (cap %d)"
                             % (WWA, above, WWA_CAP))
        log.append("ok  %s: %d lines above the marker (cap %d)"
                   % (WWA, above, WWA_CAP))
        texts[WWA] = wwa_top + wwa_bottom

        for rel, text in list(texts.items()) + list(NEW_FILES.items()):
            bad = sum(1 for ch in text if ord(ch) > 127)
            if bad:
                raise PatchError("%s: %d non-ASCII character(s) after the "
                                 "edits" % (rel, bad))
    except PatchError as exc:
        print("ERROR: %s" % exc)
        print("NOTHING was written.")
        print("Undo is not needed. Discard Changes in GitHub Desktop restores "
              "any file you changed by hand.")
        sys.exit(1)

    for rel, content in NEW_FILES.items():
        path = os.path.join(ROOT, rel)
        os.makedirs(os.path.dirname(path) or ROOT, exist_ok=True)
        with open(path, "w", encoding="utf-8", newline="") as handle:
            handle.write(content)
    for rel, text in texts.items():
        with open(os.path.join(ROOT, rel), "wb") as handle:
            handle.write(text.encode("utf-8"))
        if crlf[rel]:
            notes.append("note: %s was CRLF in the working copy; written LF"
                         % rel)
    for line in log:
        print(line)
    for line in notes:
        print(line)
    print("stamps updated: orrery_maintenance_run.py, "
          "palomas_orrery_dashboard.py, export_objects.py, "
          "osculating_cache_manager.py (docstrings); the skill's version "
          "line; the protocol's header; the ledger's header; Where We Are's "
          "date")
    print("")
    print("patch applied (%d new files, %d edits, %d move)"
          % (len(NEW_FILES), len(EDITS), len(MOVES)))
    print("")
    print("NEXT:")
    print("  1. Run orrery_maintenance_run.py. Its new Period fetch row asks JPL")
    print("     for the eight missing periods; look for 'PERIOD FETCH: PASS'.")
    print("  2. Reinstall horizons-orbital-mechanics (now 1.7) in Settings >")
    print("     Skills; save PROJECT_INSTRUCTIONS.md as")
    print("     documentation/project_instructions_v3_98.md and copy it into")
    print("     the Project instructions.")
    print("  3. Move this script into documentation/; commit and push.")
    print("Undo is Discard Changes in GitHub Desktop.")


if __name__ == "__main__":
    main()
